#include "monitor_monitor.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void monitor_monitor_initialize(void);
void monitor_monitor_notify(microkit_channel channel);
void monitor_monitor_timeTriggered(void);

volatile sb_queue_int32_t_1_t *sent_sample_queue_1;
sb_queue_int32_t_1_Recv_t sent_sample_recv_queue;
volatile sb_queue_int32_t_1_t *observed_sample_queue_1;
sb_queue_int32_t_1_Recv_t observed_sample_recv_queue;

#define PORT_FROM_MON 0

bool sent_sample_is_empty(void) {
  return sb_queue_int32_t_1_is_empty(&sent_sample_recv_queue);
}

bool get_sent_sample_poll(sb_event_counter_t *numDropped, int32_t *data) {
  return sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &sent_sample_recv_queue, numDropped, data);
}

bool get_sent_sample(int32_t *data) {
  sb_event_counter_t numDropped;
  return get_sent_sample_poll (&numDropped, data);
}

bool peek_sent_sample(int32_t *data) {
  sb_event_counter_t numDropped;
  return sb_queue_int32_t_1_peek((sb_queue_int32_t_1_Recv_t *) &sent_sample_recv_queue, &numDropped, data);
}

bool observed_sample_is_empty(void) {
  return sb_queue_int32_t_1_is_empty(&observed_sample_recv_queue);
}

bool get_observed_sample_poll(sb_event_counter_t *numDropped, int32_t *data) {
  return sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &observed_sample_recv_queue, numDropped, data);
}

bool get_observed_sample(int32_t *data) {
  sb_event_counter_t numDropped;
  return get_observed_sample_poll (&numDropped, data);
}

bool peek_observed_sample(int32_t *data) {
  sb_event_counter_t numDropped;
  return sb_queue_int32_t_1_peek((sb_queue_int32_t_1_Recv_t *) &observed_sample_recv_queue, &numDropped, data);
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_int32_t_1_Recv_init(&sent_sample_recv_queue, (sb_queue_int32_t_1_t *) sent_sample_queue_1);

  sb_queue_int32_t_1_Recv_init(&observed_sample_recv_queue, (sb_queue_int32_t_1_t *) observed_sample_queue_1);

  monitor_monitor_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      monitor_monitor_timeTriggered();
      break;
    default:
      monitor_monitor_notify(channel);
  }
}
